head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gIsurCd;
scwin.gSeq;
scwin.vScrenID = 'ULDSTF35118.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParentValue = function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !개선계획서--;
검색-- > function() {
    var url_list = "/PenaltyImposition.do?method=listPerfmDtlFile&inputMessageId=DUTY_PERFM_DTL_INOUT" + "&outputMessageId=DUTY_PERFM_DTL_INOUT";
    var url_cond = "&ISUR_CD=" + scwin.gIsurCd;
    var url = url_list + url_cond + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_imprfile_list.DataID = encodeURI(url);
    dts_imprfile_list.reset();
    $c.cm.ShowWin(grd_imprfile_list);
};




// 개선계획서파일 다운로드
scwin.fn_filedown = function(row) {
    var link = "/filedownload.do?" + "&ISUR_CD=" + dts_imprfile_list.getCellData(row, "ISUR_CD") + "&SEQ=" + dts_imprfile_list.getCellData(row, "SEQ") + "&gubun=60" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
    location.href = encodeURI(link);
};
scwin.fn_delete = function(row) {
    var vAnswer = confirm('선택한 이행 내역을 삭제처리 하시겠습니까?');
    if (vAnswer == true) {
        dts_Pnlt_Input.insertRow();
        dts_Pnlt_Input.setCellData(1, "ISUR_CD", dts_imprfile_list.getCellData(row, "ISUR_CD"));
        dts_Pnlt_Input.setCellData(1, "SEQ", dts_imprfile_list.getCellData(row, "SEQ"));
        dts_Pnlt_Input.setCellData(1, "EMP_NO", js_emp_no);
        trs_Pnlt_Input.Action = "/PenaltyImposition.do?method=deletePerfmDtlFile&inputMessageId=DUTY_PERFM_DTL_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        trs_Pnlt_Input.KeyValue = "JSP(I:pInput=dts_Pnlt_Input)";
        trs_Pnlt_Input.Post();
    }
};
scwin.dts_imprfile_list_OnLoadCompleted = function(rowcount) {
    txb_isur_cd.setValue(dts_imprfile_list.getCellData(1, "ISUR_CD"));
    txb_com_abbrv.setValue(dts_imprfile_list.getCellData(1, "COM_ABBRV"));
    $c.cm.CloseWin();
};
scwin.dts_imprfile_list_OnLoadError = function() {
    $c.stf.alert_error(dts_imprfile_list);
    $c.cm.CloseWin();
};
scwin.grd_imprfile_list_OnDblClick = function(row, colid) {
    if (colid == "FL_NM") {
        scwin.fn_filedown(row);
    } else if (colid == "DEL") {
        scwin.fn_delete(row);
    }
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_GetParentValue();
    dts_Pnlt_Input.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DUTY_PERFM_DTL_INOUT";
    dts_Pnlt_Input.reset();
    fn_Search();
};
scwin.trs_Pnlt_Input_OnFail = function() {
    $c.win.alert('trs_Pnlt_Input.OnFail() :' + trs_Pnlt_Input.ErrorMsg);
};
scwin.trs_Pnlt_Input_OnSuccess = function() {
    $c.win.alert("처리완료");

    // 화면 RELOAD
    fn_Search();
    // dataset 초기화
    dts_Pnlt_Input.removeAll();
};
